#!/usr/bin/env python3
"""
Round 205o (culprits), 14 October 2026. Needs round 204o.

Flat unless Raise is on; crowds rise only with both switches.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ['## Round 205o (14 October)\n\nNeeds round 204o (guards on its heading). No tiles patch. No app.js?v= bump.\n\n- Asked 14 October: every layer is drawn normally with both switches off;\n  Shading where points crowd alone gives flat density bands; both on, the\n  densities are raised.\n  - Rows drawn as relief (population density, livestock, NO2) swapped the\n    ground and showed their shading whenever shown; now flat colour unless\n    Raise figures as heights is on (reliefSync, run on show and by setLift).\n  - Point crowds rose with Raise alone; now only when Shading is on too\n    (pointReliefSet), and turning Shading on or off re-runs them.\n']


DIFF = ""


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round205o: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 204o" not in h.read_text(encoding="utf-8"):
        sys.exit("round205o: round 204o must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", path, check=False).returncode == 0:
        print("round205o: already applied")
    else:
        r = git("apply", "--3way", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/index.html", "map/bodies.html", "map/test.mjs", check=False)
            sys.exit("round205o: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round205o: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


if __name__ == "__main__":
    main()
